import sys, json, time, uuid

# GH #976 (PE-DP-9): the digest's shelf. Every finished digest is kept as one
# row of `./store` -- {id, at, audience_set, title, items} -- beside its
# delivery, and a read on `in_read` (op `last`) answers with the kept digests
# of the asking round. The ROUND of a row is the round of the run that made it:
# `context.digest_round`, written by the edge that started the run (the
# caller's `audience_set` on `in_digest`). A run without one is kept with an
# empty round, and an empty round covers no screen: it is never shown, and
# never widened to `*`. A SCHEDULED run (`context.digest_origin` 'schedule',
# written by the clock's edge, which overwrites whatever a caller sent) belongs
# to the member that holds this app: it is kept with the HOLDER mark and read
# back under the member's round that the builder's edge of the read stamps
# (`context.audience_set`) -- never a round the app or a caller chose
# (OR-NL-158).

TABLE = "digests"
ITEMS_MAX = 8
ITEM_CHARS = 240
TITLE = "Daily digest"
READ_LIMIT = 20
OPS = ("last",)
HOLDER = "holder"


def as_round(value):
    """A round as a sorted list of strings, or None where it is none."""
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return None
    if not isinstance(value, list) or not value:
        return None
    if not all(isinstance(x, str) and x for x in value):
        return None
    return sorted(set(value))


def covers(have, want):
    """The substrate's `Covers`: `have` holds `*` or every member of `want`."""
    have, want = as_round(have), as_round(want)
    if not have or not want:
        return False
    return "*" in have or all(m in have for m in want)


def items_of(text):
    """The digest text as at most ITEMS_MAX short items, sentence by sentence."""
    text = " ".join(str(text or "").split())
    out, cur = [], ""
    for word in text.split(" "):
        if not word:
            continue
        cur = (cur + " " + word).strip()
        if cur.endswith((".", "!", "?")) or len(cur) >= ITEM_CHARS:
            out.append(cur[:ITEM_CHARS])
            cur = ""
        if len(out) >= ITEMS_MAX:
            break
    if cur and len(out) < ITEMS_MAX:
        out.append(cur[:ITEM_CHARS])
    return out


def when(at_ms):
    return time.strftime("%Y-%m-%d %H:%M", time.gmtime(at_ms / 1000.0))


def store_call(args, tag):
    return {"header": {"route": "shelf_store"},
            "messages": [{"origin": "assistant", "type": "tool_call",
                          "id": "shelf-" + tag, "text": json.dumps(args)}]}


def keep(body, ctx, now_ms):
    """One finished digest -> one insert, with the round of its run."""
    text = ""
    for m in body.get("messages") or []:
        if m.get("origin") == "assistant" and m.get("type") == "text":
            text = m.get("text") or ""
            break
    if not text:
        return []
    if text.startswith(TITLE + ":"):
        text = text[len(TITLE) + 1:]
    if ctx.get("digest_origin") == "schedule":
        kept = HOLDER
    else:
        round_ = as_round(ctx.get("digest_round"))
        kept = json.dumps(round_) if round_ else ""
    row = {"id": str(uuid.uuid4()), "at": now_ms, "audience_set": kept,
           "title": TITLE, "items": json.dumps(items_of(text))}
    return [store_call({"operation": "insert", "table": TABLE, "row": row}, row["id"][:8])]


def answer(op, op_id, ok, extra):
    out = {"header": {"route": "answer", "op": op, "op_id": op_id},
           "messages": [], "ok": ok, "op": op}
    out.update(extra)
    return [out]


def ask(hop, ctx):
    """`in_read`: a read of the kept digests. Without a round in the asking
    context there is nobody to show anything to -- no store read at all."""
    op = str(hop.get("op") or "")
    op_id = str(ctx.get("shelf_op_id") or "")
    if op not in OPS:
        return answer(op, op_id, False, {"error": {"code": "unknown_op",
                                                    "message": "this hive reads `last` only"}})
    if not as_round(ctx.get("audience_set") or ctx.get("audience_now")):
        return answer(op, op_id, False, {"error": {"code": "no_round",
                                                   "message": "the read carries no round"}})
    return [store_call({"operation": "select", "table": TABLE,
                        "columns": ["id", "at", "audience_set", "title", "items"],
                        "order_by": [{"col": "at", "dir": "desc"}],
                        "limit": READ_LIMIT}, "read")]


def rows_of(body):
    for m in body.get("messages") or []:
        if m.get("type") == "tool_result":
            try:
                data = json.loads(m.get("text") or "")
            except ValueError:
                return None
            if isinstance(data, dict):
                data = data.get("rows")
            return data if isinstance(data, list) else None
    return None


def told(body, hop, ctx):
    """The store's answer to the read: the kept digests the asking round may
    see, newest first, each with its own round -- the screen gates them again."""
    op_id = str(ctx.get("shelf_op_id") or "")
    rows = rows_of(body)
    if rows is None or hop.get("error_code"):
        return answer("last", op_id, False, {"error": {"code": "store_error",
                                                       "message": "the shelf could not be read"}})
    asking = ctx.get("audience_set") or ctx.get("audience_now")
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        # The holder's digest takes the round of the read: the member's, stamped by
        # the builder's edge -- only the holding member's edges reach this app.
        rnd = asking if r.get("audience_set") == HOLDER else r.get("audience_set")
        if not covers(rnd, asking):
            continue
        try:
            items = json.loads(r.get("items") or "[]")
        except ValueError:
            items = []
        items = [i for i in items if isinstance(i, str)] if isinstance(items, list) else []
        at = int(r.get("at") or 0)
        out.append({"id": r.get("id") or "", "at": at, "when": when(at),
                    "title": r.get("title") or TITLE, "items": items,
                    "lead": items[0] if items else "",
                    "audience_set": as_round(rnd)})
    return answer("last", op_id, True, {"digests": out})


def main():
    doc = json.load(sys.stdin)
    body = doc.get("body") or {}
    header = (doc.get("envelope") or {}).get("header") or {}
    hop = header.get("hop") or {}
    ctx = header.get("context") or {}
    origin = ctx.get("shelf_origin")
    if origin == "read":
        if hop.get("route") == "in_read":
            return ask(hop, ctx)
        return told(body, hop, ctx)
    if any(m.get("type") == "tool_result" for m in body.get("messages") or []):
        # The store's receipt of a kept digest comes back here over the edge `./store -> ./shelf`:
        # nothing to do, and echoing it would loop.
        return []
    return keep(body, ctx, int(time.time() * 1000))


sys.stdout.write(json.dumps(main()))
